import{_ as e,o as n,c as a,a2 as s}from"./chunks/framework.BBd5PKnH.js";const i="/dev-notes/assets/Screenshot%202026-10-05%20at%2017.52.24.Efmu0lAa.png",S=JSON.parse('{"title":"Các loại Storage trên AWS: S3 vs EBS vs EFS","description":"","frontmatter":{},"headers":[],"relativePath":"notes/aws_storage_types.md","filePath":"notes/aws_storage_types.md"}'),r={name:"notes/aws_storage_types.md"};function o(l,t,c,h,g,d){return n(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="cac-loai-storage-tren-aws-s3-vs-ebs-vs-efs" tabindex="-1">Các loại Storage trên AWS: S3 vs EBS vs EFS <a class="header-anchor" href="#cac-loai-storage-tren-aws-s3-vs-ebs-vs-efs" aria-label="Permalink to &quot;Các loại Storage trên AWS: S3 vs EBS vs EFS&quot;">​</a></h1><h2 id="s3-simple-storage-service" tabindex="-1">S3 (Simple Storage Service) <a class="header-anchor" href="#s3-simple-storage-service" aria-label="Permalink to &quot;S3 (Simple Storage Service)&quot;">​</a></h2><ul><li>Lưu trữ theo đơn vị <strong>object</strong> (file được upload lên).</li><li>Tối đa <strong>5TB/file</strong>, dung lượng tổng thể gần như không giới hạn.</li><li>Mỗi bucket có tên <strong>unique</strong> trên toàn cầu.</li></ul><h3 id="storage-classes-cua-s3" tabindex="-1">Storage Classes của S3 <a class="header-anchor" href="#storage-classes-cua-s3" aria-label="Permalink to &quot;Storage Classes của S3&quot;">​</a></h3><ul><li><strong>Standard</strong>: dễ dàng upload và truy xuất, phù hợp dữ liệu truy cập thường xuyên.</li><li><strong>Intelligent-Tiering</strong>: tự động chuyển dữ liệu giữa các tier dựa trên tần suất truy cập, tính thêm phí quản lý.</li><li><strong>Standard-IA</strong> (Infrequent Access): dành cho dữ liệu ít truy cập, tính phí theo lượt truy xuất (retrieval fee).</li><li><strong>One Zone-IA</strong>: giống Standard-IA nhưng chỉ lưu trên <strong>1 Availability Zone</strong> — rẻ hơn nhưng có nguy cơ mất dữ liệu nếu AZ đó gặp sự cố.</li><li><strong>Glacier</strong>: dành cho dữ liệu lưu trữ (archive), ít truy cập, chi phí thấp.</li><li><strong>Glacier Deep Archive</strong>: lưu trữ dài hạn (long-term archive), ví dụ dữ liệu khách hàng cần giữ 10 năm — tương tự việc trước đây lưu vào băng từ (tape), chi phí thấp nhất nhưng thời gian truy xuất lâu nhất.</li></ul><h2 id="ebs-elastic-block-storage" tabindex="-1">EBS (Elastic Block Storage) <a class="header-anchor" href="#ebs-elastic-block-storage" aria-label="Permalink to &quot;EBS (Elastic Block Storage)&quot;">​</a></h2><ul><li>Là loại <strong>network-attached storage</strong>, chỉ dùng cho EC2.</li><li>Mỗi volume EBS chỉ được gắn (attach) vào <strong>1 EC2 tại một thời điểm</strong>.</li><li>Bị giới hạn trong <strong>1 Availability Zone</strong> — EBS ở AZ1 chỉ kết nối được với EC2 cũng nằm ở AZ1.</li><li>Có hai loại chính: <strong>gp</strong> (general purpose) và <strong>io</strong> (dành cho input/output tốc độ cao).</li><li>Khi tạo một EC2 mới, mặc định sẽ tạo kèm một EBS volume (root volume).</li></ul><h2 id="efs-elastic-file-system" tabindex="-1">EFS (Elastic File System) <a class="header-anchor" href="#efs-elastic-file-system" aria-label="Permalink to &quot;EFS (Elastic File System)&quot;">​</a></h2><ul><li>Có thể được <strong>mount vào nhiều EC2 cùng lúc</strong>.</li><li>Nhiều EC2 có thể cùng <strong>ghi (write)</strong> vào chung một EFS — phù hợp cho các workload cần chia sẻ file giữa nhiều instance.</li></ul><h2 id="tong-quan-so-sanh" tabindex="-1">Tổng quan so sánh <a class="header-anchor" href="#tong-quan-so-sanh" aria-label="Permalink to &quot;Tổng quan so sánh&quot;">​</a></h2><p><img src="'+i+'" alt="So sánh S3, EBS, EFS"></p><table tabindex="0"><thead><tr><th></th><th>S3</th><th>EBS</th><th>EFS</th></tr></thead><tbody><tr><td>Đơn vị lưu trữ</td><td>Object</td><td>Block</td><td>File</td></tr><tr><td>Gắn với</td><td>Truy cập qua API/HTTP, không gắn trực tiếp vào EC2</td><td>1 EC2 tại 1 thời điểm</td><td>Nhiều EC2 cùng lúc</td></tr><tr><td>Phạm vi AZ</td><td>Toàn vùng (region)</td><td>1 AZ</td><td>Nhiều AZ</td></tr></tbody></table>',12)])])}const p=e(r,[["render",o]]);export{S as __pageData,p as default};
